; Every 16 calls ($40), it checks the keys and updates voice 3. When the dog attacks ($1f31 = 2), $9698 makes the sound. Else an overheated mower flashes sprite 0. The mower noise falls in pitch until $3c is 0.
sound_key_tick
        dec sound_task_timer
        bne score_add_lawn_return
        lda #$10
        sta sound_task_timer
        jsr check_keys                  ; The pause and music keys.
        lda dog_mode
        cmp #$02
        bne sound_mower
        jmp dog_attack_sound
sound_mower
        lda mower_overheated
        bne sound_overheated
        lda mow_sound_on
        beq score_add_lawn_return
        dec sfx_pitch
        beq sound_noise_off
        lda sfx_pitch
        sta FREHI3
        rts
sound_noise_off
        lda #$00
        sta mow_sound_on
        lda #$00
        sta VCREG3
sound_tick_return
        rts
; The mower is overheated ($3e = 1). Sprite 0 changes colour, the colour sets the pitch of voice 3, and the speed $32 stays 0.
sound_overheated
        cmp #$01
        bne sound_tick_return
        inc SP0COL
        lda SP0COL
        asl
        asl
        sta FREHI3
        lda #$00
        sta gordon_speed
        sta VCREG3
        lda #$11
        sta VCREG3
        rts
